import { expect, test } from "bun:test";
import { readConfig, readWorkerConfig } from "./src/config.ts";

for (const read of [readConfig, readWorkerConfig]) {
	test(`${read.name} supplies defaults`, () => {
		expect(read({})).toEqual({ host: "127.0.0.1", port: 8080, secure: false });
	});
	test(`${read.name} trims and parses values`, () => {
		expect(
			read({
				APP_HOST: " example.test ",
				APP_PORT: "443",
				APP_SECURE: " TRUE ",
			}),
		).toEqual({ host: "example.test", port: 443, secure: true });
	});
	test(`${read.name} rejects invalid booleans`, () => {
		expect(() => read({ APP_SECURE: "yes" })).toThrow(
			"APP_SECURE must be true or false",
		);
	});
}

export interface Config {
	host: string;
	port: number;
	secure: boolean;
}

export function readConfig(env: Record<string, string | undefined>): Config {
	const host = env.APP_HOST ? env.APP_HOST.trim() : "127.0.0.1";
	const rawPort = env.APP_PORT ? env.APP_PORT.trim() : "8080";
	const port = Number(rawPort);
	if (!Number.isInteger(port) || port < 1 || port > 65535) {
		throw new Error("APP_PORT must be an integer from 1 to 65535");
	}
	const secure = env.APP_SECURE
		? env.APP_SECURE.trim().toLowerCase() === "true"
		: false;
	return { host, port, secure };
}

export function readWorkerConfig(
	env: Record<string, string | undefined>,
): Config {
	const host = env.APP_HOST ? env.APP_HOST.trim() : "127.0.0.1";
	const rawPort = env.APP_PORT ? env.APP_PORT.trim() : "8080";
	const port = Number(rawPort);
	if (!Number.isInteger(port) || port < 1 || port > 65535) {
		throw new Error("APP_PORT must be an integer from 1 to 65535");
	}
	const rawSecure = env.APP_SECURE
		? env.APP_SECURE.trim().toLowerCase()
		: "false";
	if (rawSecure !== "true" && rawSecure !== "false") {
		throw new Error("APP_SECURE must be true or false");
	}
	return { host, port, secure: rawSecure === "true" };
}

